import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    if x.shape != (5,):
        raise ValueError("Input must be a 1D NumPy array of shape (5,)")

    q = np.array([1.0, 0.5, 0.25, 0.125, 0.0625])
    skew = 0.1 * np.sum(x)
    fitness = np.sum(q * x**2 * (1 + skew)) + 0.05 * np.sum(x * np.roll(x, 1))
    gaussian_kernel = np.exp(-np.sum(np.abs(x - np.mean(x))) / 2.0) # Manhattan distance
    return (fitness * (1 + 0.05 * gaussian_kernel)) * 0.8 + 0.02 * np.sum(np.abs(x))

